   const showKind=kind=>{const legacy=b.querySelector('[data-legacy-presets]');if(legacy)legacy.hidden=!['med','fluid'].includes(kind);b.querySelector('[data-preset-tools]').hidden=!['med','fluid'].includes(kind);b.querySelector('[data-preset-status]').hidden=!['med','fluid'].includes(kind);b.querySelectorAll('[data-kind-panel]').forEach(x=>x.hidden=x.dataset.kindPanel!==kind);b.querySelectorAll('[data-kind]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.kind===kind)));};b.querySelectorAll('[data-kind]').forEach(btn=>btn.onclick=()=>showKind(btn.dataset.kind));
