   function resultActions(f,text){text=domestic?.report(f,text)||text;text=privateLibrary?.report(f,text)||text;text=simple?.report(f,text)||text;const actions=f.querySelector('[data-result-actions]');actions.hidden=false;actions.innerHTML='<label class="pt-choice"><input data-checked type="checkbox">환자·입력값·단위·결과를 확인했습니다.</label><div class="pt-bar"><button type="button" data-copy disabled>결과 복사</button><button type="button" data-print disabled>결과 인쇄</button></div><p data-copy-state role="status"></p>';const report=`CARESTEP 계산 결과\n${patientLabel()}\n${weightInfo?'기록 체중 측정일 '+(weightInfo.weightDate||'미기록'):'체중 직접 입력'}\n${new Date().toLocaleString('ko-KR')} 계산\n${text}\n계산 확인용 · 실제 처방 및 투약 여부는 별도 확인`;actions.querySelector('[data-checked]').onchange=e=>actions.querySelectorAll('button').forEach(x=>x.disabled=!e.target.checked);actions.querySelector('[data-copy]').onclick=async()=>{try{await navigator.clipboard.writeText(report);actions.querySelector('[data-copy-state]').textContent='계산 결과를 복사했습니다.';}catch{actions.querySelector('[data-copy-state]').textContent='복사하지 못했습니다. 결과를 선택해 복사해주세요.';}};actions.querySelector('[data-print]').onclick=()=>{const area=document.createElement('section');area.className='pt-print-report pt-pre';area.textContent=report;document.body.append(area);document.body.classList.add('pt-printing');try{window.print();}finally{document.body.classList.remove('pt-printing');area.remove();}};}
   b.querySelectorAll('form[data-calc]').forEach(f=>{f.oninput=e=>{if(!e.target.closest('[data-result-actions]'))clearResults();};f.onchange=e=>{if(e.target.closest('[data-result-actions]'))return;if(e.target.name==='form'||e.target.name==='strengthUnit')f.elements.concentration.value='';if(['doseBasis','doseUnit'].includes(e.target.name))f.elements.dose.value='';if(e.target.name==='doseBasis'&&f.elements.bsa)f.elements.bsa.value='';if(e.target.name==='mode')f.elements.rate.value='';if(f===med&&e.target.name==='doseUnit'&&f.elements.doseUnit.value==='T'){f.elements.form.value='tablet';f.elements.strengthUnit.value='T';f.elements.concentration.value='1';}else if(f===med&&e.target.name==='strengthUnit'&&f.elements.strengthUnit.value==='T'){f.elements.form.value='tablet';f.elements.concentration.value='1';}clearResults();layout();};f.onsubmit=e=>{e.preventDefault();if(!alive())return;if((a.patient()?.id||'')!==initialPatientId){clearResults();void advancedCalculator();return;}const v=Object.fromEntries(new FormData(f)),c=g.PracticeCalculators,out=f.querySelector('output');try{const context=referenceUI?.context(f,v)||'';let text;if(f.dataset.calc==='dose'){const r=c.prescription({...v,strength:v.concentration,totalDoses:v.courseMode==='total'?v.totalDoses:''});text=`${v.doseBasis==='fixed'?`고정량 ${v.dose} ${v.doseUnit}/마리/회 · 확인 체중 ${v.weight} kg`:v.doseBasis==='bsa'?`확인 체표면적 ${v.bsa} m² × ${v.dose} ${v.doseUnit}/m²/회 · 체중 ${v.weight} kg`:`체중 ${v.weight} kg × ${v.dose} ${v.doseUnit}/kg/회`}\n1회 총량 ${c.format(v.doseUnit==='T'?r.tablets:v.doseUnit==='U'?r.activity:r.mg)} ${v.doseUnit==='T'?'정':v.doseUnit==='U'?'U':'mg'}\n제품 ${v.concentration} ${v.strengthUnit}/${({tablet:'정',capsule:'캡슐',liquid:'mL'})[v.form]}\n1회 투여량 ${c.format(r.amount)} ${r.unit}/회\n총 ${r.totalDoses}회 · 전체 필요량 ${c.format(r.total)} ${r.unit}`;}else if(f.dataset.calc==='fluid'){const r=c.fluid(v);text=`입력 방식: ${f.elements.mode.selectedOptions[0].textContent}\n${v.mode==='weight'?`체중 ${v.weight} kg × ${v.rate} mL/kg/hr`:v.mode==='rate'?`설정 ${v.rate} mL/hr`:`총 ${v.volume} mL ÷ ${v.hours} 시간`}\n주입 속도 ${c.format(r.rate)} mL/hr${r.volume!==null?`\n${v.hours}시간 동안 ${c.format(r.volume)} mL`:''}${r.hours!==null?`\n${v.volume} mL 소요시간 ${c.format(r.hours)}시간`:''}${r.drops!==null?`\n세트 ${v.factor} gtt/mL · ${c.format(r.drops)} gtt/min`:''}`;}else if(f.dataset.calc==='convert')text=`${v.value} ${v.from} = ${c.format(c.convert(v.value,v.from,v.to))} ${v.to}`;else{const r=c.dilute(v.stock,v.target,v.volume);text=`${v.stock} mg/mL → ${v.target} mg/mL\n원액 ${c.format(r.stockML)} mL\n최종 ${v.volume} mL가 되도록 희석액 보충\n계산상 희석액 ${c.format(r.diluentML)} mL`;}out.className='pt-output pt-pre';out.textContent=context+text;resultActions(f,context+text+(referenceUI?.reportSource(f)||''));}catch(e){error(out,e);f.querySelector('[data-result-actions]').hidden=true;}};});
   async function loadPresets(){try{const r=await a.request('/practice/presets?protocols=1&formulary=1');if(!alive())return;presets={...r,items:r.items.filter(x=>x.body.kind!=='protocol')};simple?.loaded({...r,items:r.items.filter(p=>!p.formularyIssue&&!p.body.formulary)});batch?.loaded(r);b.querySelector('[data-preset]').innerHTML='<option value="">서식 선택 · 선택사항</option>'+presets.items.filter(x=>!x.formularyIssue&&!x.body.formulary).map(x=>`<option value="${x.id}">${esc(x.body.title)}</option>`).join('');b.querySelector('[data-preset-manage]').hidden=!r.canManage;workspace?.presetsLoaded();return r;}catch(e){presets={items:[],canManage:false};simple?.failed();batch?.failed();if(alive())b.querySelector('[data-preset-status]').textContent='승인 서식을 불러오지 못했습니다. 값을 직접 입력할 수 있습니다.';}}void loadPresets();b.querySelector('[data-preset]').onchange=e=>{clearResults();const p=presets.items.find(x=>x.id===e.target.value);if(!p)return;const v=p.body;referenceUI?.resetPreset();workspace?.presetChanged();if(v.kind==='fluid'){showKind('fluid');fluid.elements.factor.value=v.value;}else{showKind('med');med.elements.form.value=v.kind;med.elements.concentration.value=v.value;med.elements.strengthUnit.value=v.unit;med.elements.dose.value='';}layout();simple?.legacyApplied();b.querySelector('[data-preset-status]').textContent=`${v.title} · 확인 ${p.approver_name||'병원 의료진'} · ${stamp(p.updated_at)} · ${v.note||'제품 표시와 다시 대조해주세요.'}`;};b.querySelector('[data-preset-manage]').onclick=()=>presetManager(presets,loadPresets,p=>domestic?.edit(p));
