  function presetManager(presets,reload,editFormulary){const d=modal('우리 병원 약품·계산 서식 관리','<p>국내 제품 검색에서 확인한 약품은 이곳에 저장됩니다. 환자별 체중·처방량은 저장하지 않습니다. 제품 함량·단위 또는 수액 세트 점적계수만 확인 후 등록합니다.</p><button data-new>승인 서식 만들기</button>'+presets.items.map(p=>`<article class="pt-card"><b>${esc(p.body.title)}</b><p>${p.body.formulary?.calculatorReady===false?'제품 등록됨 · 계산 함량 미설정':esc(p.body.value)+' '+(p.body.kind==='fluid'?'gtt/mL':esc(p.body.unit)+'/'+({tablet:'정',capsule:'캡슐',liquid:'mL'})[p.body.kind])}${p.body.formulary?.calculationBasis?' · 계산 기준 '+esc(p.body.formulary.calculationBasis):''} · ${esc(p.approver_name||'병원 의료진')}</p>${p.formularyIssue?'<p class="pt-error">'+esc(p.formularyIssue)+'</p>':''}${p.body.formulary?'<p>자동 연결: '+esc(p.body.formulary.aliases.join(', '))+' · '+p.body.formulary.species.map(s=>s==='dog'?'개':'고양이').join('·')+' · '+({oral:'경구',injection:'주사',other:'계산 경로 미설정'})[p.body.formulary.route]+'</p>':''}<button data-edit="${p.id}">수정</button> <button data-remove="${p.id}">보관</button></article>`).join(''));d.querySelector('[data-new]').onclick=()=>presetEdit(null,reload);d.querySelectorAll('[data-edit]').forEach(btn=>btn.onclick=()=>{const p=presets.items.find(p=>p.id===btn.dataset.edit);if(p.body.formulary&&editFormulary)editFormulary(p);else presetEdit(p,reload);});d.querySelectorAll('[data-remove]').forEach(btn=>btn.onclick=()=>action(btn,()=>a.request('/practice/presets/'+btn.dataset.remove,{method:'DELETE',body:JSON.stringify({revision:presets.items.find(p=>p.id===btn.dataset.remove).revision})}),async()=>{close();await reload();}));}
  function presetEdit(old,reload){const v=old?.body||{},d=modal('계산 서식 확인·저장',`<form><label>제품·서식 이름<input name="title" maxlength="100" value="${esc(v.title||'')}" required></label><label>종류<select name="kind"><option value="liquid">액상 · 1mL당 함량</option><option value="tablet">정제 · 1정당 함량</option><option value="fluid">수액 세트 · gtt/mL</option></select></label><label>함량·점적계수<input name="value" inputmode="decimal" value="${v.value||''}" required></label><label>약물 함량 단위 · 수액 세트는 gtt/mL 적용<select name="unit"><option>mg</option><option>mcg</option></select></label>${v.formulary?'<label>자동 연결할 약물명·약칭 · 쉼표로 구분<input name="aliases" maxlength="1500" value="'+esc(v.formulary.aliases.join(', '))+'"></label><p class="pt-help">제품·함량 변경은 보관 후 제품 검색에서 다시 등록하세요.</p>':''}<label>제품 확인 메모<textarea name="note" maxlength="500">${esc(v.note||'')}</textarea></label><label class="pt-choice"><input name="confirm" type="checkbox" required>제품의 함량·농도·단위를 확인했습니다.</label><button class="pt-primary">확인 후 서식 저장</button></form>`),f=d.querySelector('form');f.elements.kind.value=v.kind||'liquid';f.elements.unit.value=v.unit||'mg';if(v.formulary)for(const name of ['title','kind','value','unit']){f.elements[name].disabled=true;}f.onsubmit=e=>{e.preventDefault();action(f.querySelector('button'),()=>a.request('/practice/presets'+(old?'/'+old.id:''),{method:old?'PUT':'POST',body:JSON.stringify({...v,...Object.fromEntries(new FormData(f)),aliases:f.elements.aliases?.value.split(',').map(x=>x.trim()).filter(Boolean),confirm:f.elements.confirm.checked,revision:old?.revision})}),async()=>{close();await reload();});};}

